// JAH demo program — Branch counting (toy)
"use strict";
var __checks=[];
function check(l,g,w){__checks.push([l,g,w]);}
function branches(measurements){ return Math.pow(2,measurements); }
check("10 binary measurements \u2192 1024 branches", branches(10), 1024);
check("exponential branching", branches(20)>1000000, true);
check("interpretation, not fact", 'interpretation', "interpretation");
var __ok=true;
__checks.forEach(function(c){var ok=String(c[1])===String(c[2]);__ok=ok&&__ok;console.log((ok?"PASS":"FAIL")+" | "+c[0]+" => "+c[1]);});
console.log(__ok?"ALL CHECKS PASSED":"SOME CHECKS FAILED");
if(!__ok){throw new Error("demo self-check failed");}

